formulas.expression:
VALUE(
  LEFT(
    RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("X3860 Channel A Delay:", {!OutputFormatFetched}) - LEN("X3860 Channel A Delay:")),
    FIND("<", RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("X3860 Channel A Delay:", {!OutputFormatFetched}) - LEN("X3860 Channel A Delay:"))) - 1
  )
)

VALUE(
  LEFT(
    RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("X3860 Channel B Delay:", {!OutputFormatFetched}) - LEN("X3860 Channel B Delay:")),
    FIND("<", RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("X3860 Channel B Delay:", {!OutputFormatFetched}) - LEN("X3860 Channel B Delay:"))) - 1
  )
)
